namespace Otus.Modulo.Animais
{
	[Module(ModuleName = "AnimalModulo", OnDemand = true)]
	[ModuleDependency("PessoaModulo")]
	[ModuleDependency("RelatorioModulo")]
	[ModuleDependency("AgendamentoModulo")]
	public class AnimalModulo : IModule
	{
		private readonly IUnityContainer _container;

		public AnimalModulo(IUnityContainer container)
		{
			_container = container;
		}

		public void Initialize()
		{
			UnityExtensions.RegisterTypeForNavigation<AnimaisView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<AnimalListaView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<AnimalFichaAdicionarView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<AnimalFichaAtualizarView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<EspecieAnimalListaView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<EspecieAnimalFichaAdicionarView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<RacaAnimalListaView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<RacaAnimalFichaAdicionarView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<RecorrenciaFichaView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<ProximasAplicacoesFichaView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<DoseFichaAdicionarView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<TipoAdministracaoFichaAdicionarView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<PosologiaListaView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<PosologiaFichaAdicionarView>(_container, (string)null);
			UnityExtensions.RegisterTypeForNavigation<PosologiaFichaAtualizarView>(_container, (string)null);
		}
	}
}
