				if (today.Day < value.Day)
				{
					num--;
				}
				if (num < 1)
				{
					int days = (today - value).Days;
					if (days != 1)
					{
						return days + " dias";
					}
					return "1 dia";
				}
				if (num < 12)
				{
					if (num != 1)
					{
						return num + " meses";
					}
					return "1 mês";
				}
				int num2 = num / 12;
				if (num2 != 1)
				{
					return num2 + " anos";
				}
				return "1 ano";
			}
		}

