		private void ObterImagens(string animalReferencia)
		{
			LoaderProcessoService.MostrarLoader("Obtendo imagens...");
			new Thread((ThreadStart)async delegate
			{
				try
				{
					IEnumerable<AnexoAnimalDto> imagens = default(IEnumerable<AnexoAnimalDto>);
					_ = imagens;
					imagens = await _service.Canal<IAnimalModuleService, Task<IEnumerable<AnexoAnimalDto>>>((Func<IAnimalModuleService, Task<IEnumerable<AnexoAnimalDto>>>)((IAnimalModuleService service) => service.ObterImagens(animalReferencia)));
					ThreadPrincipal.Executar((Action)delegate
					{
						//IL_003c: Unknown result type (might be due to invalid IL or missing references)
						//IL_0046: Expected O, but got Unknown
						foreach (AnexoAnimalDto item in imagens)
						{
							ImagemViewModel adicionar = new ImagemViewModel(HelperImage.ToBitmapSource(item.Image), item.FileName, HelperDate.FormatarData(item.DataCriacao, (FormatoData)6));
							if (!Imagens.Existe((Expression<Func<ImagemViewModel, bool>>)((ImagemViewModel x) => HelperImage.ToArrayByte(x.Imagem).SequenceEqual(HelperImage.ToArrayByte(adicionar.Imagem)))) && !HelperBool.In<string>(item.FileName, (from x in base.Dto.AnexosExluidos
								where x.IsImage
								select x into anexos
								select anexos.FileName).ToArray()))
							{
								Imagens.Adicionar(adicionar);
							}
						}
					});
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception e = ex2;
					ThreadPrincipal.Executar((Action)delegate
					{
						HelperException.ShowLastException(e, "", false, false);
					});
				}
				finally
				{
					ThreadPrincipal.Executar((Action)LoaderProcessoService.EsconderLoader);
				}
			}).Start();
		}

		private void ObterArquivos(string animalReferencia)
		{
			LoaderProcessoService.MostrarLoader("Obtendo arquivos...");
			new Thread((ThreadStart)async delegate
			{
				try
				{
					IEnumerable<AnexoAnimalDto> arquivos = default(IEnumerable<AnexoAnimalDto>);
					_ = arquivos;
					arquivos = await _service.Canal<IAnimalModuleService, Task<IEnumerable<AnexoAnimalDto>>>((Func<IAnimalModuleService, Task<IEnumerable<AnexoAnimalDto>>>)((IAnimalModuleService service) => service.ObterArquivos(animalReferencia)));
					ThreadPrincipal.Executar((Action)delegate
					{
						//IL_003d: Unknown result type (might be due to invalid IL or missing references)
						//IL_0047: Expected O, but got Unknown
						foreach (AnexoAnimalDto item in arquivos)
						{
							ArquivoViewModel adicionar = new ArquivoViewModel(item.Arquivo, item.FileName, item.NomeArquivo, HelperDate.FormatarData(item.DataCriacao, (FormatoData)6));
							if (!Arquivos.Existe((Expression<Func<ArquivoViewModel, bool>>)((ArquivoViewModel x) => x.Arquivo.SequenceEqual(adicionar.Arquivo))) && !HelperBool.In<string>(item.FileName, (from x in base.Dto.AnexosExluidos
								where !x.IsImage
								select x into anexo
								select anexo.FileName).ToArray()))
							{
								Arquivos.Adicionar(adicionar);
							}
						}
					});
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception e = ex2;
					ThreadPrincipal.Executar((Action)delegate
					{
						HelperException.ShowLastException(e, "", false, false);
					});
				}
				finally
				{
					ThreadPrincipal.Executar((Action)LoaderProcessoService.EsconderLoader);
				}
			}).Start();
		}

		private void AbrirAnexoImagem(ImagemViewModel obj)
		{
			string text = Path.Combine(Path.GetDirectoryName(Process.GetCurrentProcess().MainModule.FileName), "Temp");
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text).Attributes = FileAttributes.Directory;
			}
			try
			{
				File.WriteAllBytes(Path.Combine(text, obj.FileName), HelperImage.ToArrayByte(obj.Imagem));
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Ocorreu um erro ao salvar a imagem na pasta " + text, false, System.Windows.HorizontalAlignment.Center);
			}
			Process.Start(Path.Combine(text, obj.FileName));
		}

		private void AbrirAnexoArquivo(ArquivoViewModel obj)
		{
			string text = Path.Combine(Path.GetDirectoryName(Process.GetCurrentProcess().MainModule.FileName), "Temp");
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text).Attributes = FileAttributes.Directory;
			}
			try
			{
				byte[] bytes = Convert.FromBase64String(obj.Arquivo);
				File.WriteAllBytes(Path.Combine(text, obj.FileName), bytes);
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Ocorreu um erro ao salvar arquivo na pasta " + text, false, System.Windows.HorizontalAlignment.Center);
			}
			Process.Start(Path.Combine(text, obj.FileName));
		}

		public override void AtualizarDto<T>(ref T dto)
		{
			object obj = dto;
			AnimalDto val = (AnimalDto)((obj is AnimalDto) ? obj : null);
			if (val != null)
			{
				List<AnexoAnimalDto> first = HelperIEnumerable.ToListEmptyWhenNull<AnexoAnimalDto>(((IEnumerable<ImagemViewModel>)Imagens.Itens).Select((Func<ImagemViewModel, AnexoAnimalDto>)((ImagemViewModel x) => new AnexoAnimalDto
				{
					FileName = x.FileName,
					Image = HelperImage.Compress(x.Imagem),
					IsImage = true
				})));
				List<AnexoAnimalDto> first2 = HelperIEnumerable.ToListEmptyWhenNull<AnexoAnimalDto>(((IEnumerable<ImagemViewModel>)ImagensExcluidas.Itens).Select((Func<ImagemViewModel, AnexoAnimalDto>)((ImagemViewModel x) => new AnexoAnimalDto
				{
					FileName = x.FileName,
					IsImage = true
				})));
				List<AnexoAnimalDto> second = HelperIEnumerable.ToListEmptyWhenNull<AnexoAnimalDto>(((IEnumerable<ArquivoViewModel>)Arquivos.Itens).Select((Func<ArquivoViewModel, AnexoAnimalDto>)((ArquivoViewModel x) => new AnexoAnimalDto
				{
					FileName = x.FileName,
					Arquivo = x.Arquivo,
					NomeArquivo = x.NomeArquivo
				})));
				List<AnexoAnimalDto> second2 = HelperIEnumerable.ToListEmptyWhenNull<AnexoAnimalDto>(((IEnumerable<ArquivoViewModel>)ArquivosExcluidos.Itens).Select((Func<ArquivoViewModel, AnexoAnimalDto>)((ArquivoViewModel x) => new AnexoAnimalDto
				{
					FileName = x.FileName
				})));
				val.Anexos = first.Union(second);
				val.AnexosExluidos = first2.Union(second2);
				base.AtualizarDto<AnimalDto>(ref val);
			}
		}
	}
