			}
			return lote.Lotes.Where((LoteDto a) => HelperObject.Is<EstoqueGradeDto>((object)a.Estoque)).Select(delegate(LoteDto x)
			{
				ConsultaFichaManutencaoViewModel consultaFichaManutencaoViewModel = this;
