		public override void AtualizarDto<T>(ref T dto)
		{
			object obj = dto;
			ConsultaDto val = (ConsultaDto)((obj is ConsultaDto) ? obj : null);
			if (!HelperObject.IsNull((object)val))
			{
				DtoAtualizado = val;
				val.Veterinario = Veterinarios?.ItemSelecionado;
				ConsultaDto obj2 = val;
				Lista<PessoaDto> veterinarios = Veterinarios;
				object veterinarioReferencia;
				if (veterinarios == null)
				{
					veterinarioReferencia = null;
				}
				else
				{
					PessoaDto itemSelecionado = veterinarios.ItemSelecionado;
					veterinarioReferencia = ((itemSelecionado != null) ? ((EntityBaseDto)itemSelecionado).Id : null);
				}
				obj2.VeterinarioReferencia = (string)veterinarioReferencia;
				val.Anamnese = Anamnese;
				val.SuspeitaClinica = SuspeitaClinica;
				val.SinaisClinicos = SinaisClinicos;
				val.Diagnostico = Diagnostico;
				val.Tratamento = Tratamento;
				val.ExamesSolicitados = ExamesSolicitados;
				val.Observacao = Observacao;
				val.DataConsulta = DataConsulta ?? DateTime.MinValue;
				val.Agendado = Agendado;
				val.Itens = Itens;
				val.DavOsGerado = DavOsGerado;
				((ViewModelBase<ConsultaDto>)(object)this).UpdateModel(val);
				((ViewModelDtoBase<ConsultaDto>)(object)this).AtualizarDto<ConsultaDto>(ref val);
			}
		}

