		private void Imprimir(object obj)
		{
			ImpressoAtestadoDto val = (ImpressoAtestadoDto)((obj is ImpressoAtestadoDto) ? obj : null);
			if (val.AtestadoTransito)
			{
				XtraReportExtensions.ShowPreviewDialog((IReport)(object)((Relatorio)new ImpressoAtestadoTransito(val, _animalDto)).Processar());
			}
			else if (!HelperString.IsNullOrEmpty(val.TituloImpressoGenerico) || !HelperString.IsNullOrEmpty(val.ConteudoImpressoGenerico))
			{
				XtraReportExtensions.ShowPreviewDialog((IReport)(object)((Relatorio)new ImpressoAtestadoGenerico(val, _animalDto)).Processar());
			}
			else
			{
				XtraReportExtensions.ShowPreviewDialog((IReport)(object)((Relatorio)new ImpressoAtestadoVacinacao(val, _animalDto)).Processar());
			}
		}

		public void ObterVeterinarios(string veterinarioReferencia)
		{
			IEnumerable<PessoaDto> result = DadosSistema.GetService().Canal<IPessoaModuleService, Task<IEnumerable<PessoaDto>>>((Func<IPessoaModuleService, Task<IEnumerable<PessoaDto>>>)((IPessoaModuleService service) => service.ObterPessoasAtivasPorTipoCadastro((TipoPessoaCadastro)8))).Result;
			if (HelperObject.IsNotNull((object)Veterinarios))
			{
				Veterinarios.AlterouItemSelecionadoEvent -= VeterinariosOnAlterouItemSelecionadoEvent;
			}
			Veterinarios = new Lista<PessoaDto>();
			Veterinarios.AdicionarSemPosicionar(result);
			if (!HelperString.IsNullOrEmpty(veterinarioReferencia))
			{
				Veterinarios.Posicionar((Expression<Func<PessoaDto, bool>>)((PessoaDto x) => ((EntityBaseDto)x).Id.Equals(veterinarioReferencia)));
				Lista<PessoaDto> veterinarios = Veterinarios;
				object veterinarioNome;
				if (veterinarios == null)
				{
					veterinarioNome = null;
				}
				else
				{
					PessoaDto itemSelecionado = veterinarios.ItemSelecionado;
					veterinarioNome = ((itemSelecionado != null) ? HelperString.ToStringEmptyWhenNull(itemSelecionado.Nome) : null);
				}
				VeterinarioNome = (string)veterinarioNome;
				Lista<PessoaDto> veterinarios2 = Veterinarios;
				object veterinarioCrmv;
				if (veterinarios2 == null)
				{
					veterinarioCrmv = null;
				}
				else
				{
					PessoaDto itemSelecionado2 = veterinarios2.ItemSelecionado;
					if (itemSelecionado2 == null)
					{
						veterinarioCrmv = null;
					}
					else
					{
						FisicaDto fisica = itemSelecionado2.Fisica;
						if (fisica == null)
						{
							veterinarioCrmv = null;
						}
						else
						{
							PrescritorDto prescritor = fisica.Prescritor;
							veterinarioCrmv = ((prescritor != null) ? prescritor.Numero : null);
						}
					}
				}
				VeterinarioCrmv = (string)veterinarioCrmv;
			}
			Veterinarios.AlterouItemSelecionadoEvent += VeterinariosOnAlterouItemSelecionadoEvent;
		}

		private void VeterinariosOnAlterouItemSelecionadoEvent(object sender, PessoaDto pessoaDto1)
		{
			VeterinarioNome = Veterinarios.ItemSelecionado.Nome;
			VeterinarioCrmv = Veterinarios.ItemSelecionado.Fisica.Prescritor.Numero;
		}

		public static System.ComponentModel.DataAnnotations.ValidationResult ValidarTituloGenerico(object value, ValidationContext context)
		{
			string text = value as string;
			if (_tipoImpresso != 2)
			{
				return System.ComponentModel.DataAnnotations.ValidationResult.Success;
			}
			if (!HelperString.IsNullOrEmpty(text) && _tipoImpresso == 2)
			{
				return System.ComponentModel.DataAnnotations.ValidationResult.Success;
			}
			return new System.ComponentModel.DataAnnotations.ValidationResult(string.Empty);
		}

		public string ObterObservacaoPadrao(string referencia)
		{
			return DadosSistema.GetService().Canal<IObservacaoDadoAdicionalModuleService, ObservacaoDadoAdicionalDto>((Func<IObservacaoDadoAdicionalModuleService, ObservacaoDadoAdicionalDto>)((IObservacaoDadoAdicionalModuleService x) => x.ObterObservacao(referencia))).Conteudo;
		}

		public override void ProjectedAsViewModel()
		{
			PodePesquisarObservacao = DadosSistema.PodeExecutarFuncao(new Type[3]
			{
				typeof(Gerencial),
				typeof(Administrador),
				typeof(AdministradorIndustria)
			});
			DataImpressao = ((((ViewModelDtoBase<ImpressoAtestadoDto>)(object)this).Dto.DataInclusao == DateTime.MinValue) ? DateTime.Now : ((ViewModelDtoBase<ImpressoAtestadoDto>)(object)this).Dto.DataInclusao);
			AtestadoTransito = ((ViewModelDtoBase<ImpressoAtestadoDto>)(object)this).Dto.AtestadoTransito;
			TipoImpresso = new Lista<KeyValuePair<int, string>>();
			TipoImpresso.Adicionar(new KeyValuePair<int, string>(0, "Atestado de vacinação"));
