		private void RemoverItem(object item)
		{
			LoaderProcessoService.MostrarLoader(DadosSistema.IsPaf ? "Cancelando item" : "Excluindo item");
			try
			{
				ItemDto itemDto = (ItemDto)((item is ItemDto) ? item : null);
				if (DadosSistema.IsPaf)
				{
					itemDto.Cancelado = true;
					return;
				}
				IEnumerable<ItemDto> enumerable = Itens.Where((ItemDto x) => x.Numero != itemDto.Numero);
				Itens = HelperIEnumerable.ToListEmptyWhenNull<ItemDto>(enumerable);
			}
			catch (Exception ex)
			{
				HelperException.ShowLastException(ex, "", false, false);
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

