		public void ObterAgendamentos(string id)
		{
			if (Helper.IsEmpty((IEnumerable)id))
			{
				return;
			}
			IEnumerable<AgendamentoDto> result = DadosSistema.GetService().Canal<IAnimalModuleService, Task<IEnumerable<AgendamentoDto>>>((Func<IAnimalModuleService, Task<IEnumerable<AgendamentoDto>>>)((IAnimalModuleService service) => service.PesquisarAgendamentoPorAnimal(DateTime.MinValue, DateTime.MaxValue, id))).Result;
			foreach (AgendamentoDto agendamentoDto in result)
			{
				agendamentoDto.DescricaoMotivo = Rotulo.Itens.FirstOrDefault((Rotulo x) => x.Codigo.Equals(agendamentoDto.Label)).Descricao;
				agendamentoDto.DescricaoStatus = Situacao.Itens.FirstOrDefault((Situacao x) => x.Codigo.Equals(agendamentoDto.Status)).Descricao;
			}
			SetarAgendamentos(result);
		}

