				Itens.Adicionar(agendamentosDto);
				Itens.PosicionarNoPrimeiro();
			});
		}

		private bool PodeIniciarConversaWhatsApp()
		{
			Lista<AgendamentoDto> itens = Itens;
			object value;
			if (itens == null)
			{
				value = null;
			}
			else
			{
				AgendamentoDto itemSelecionado = itens.ItemSelecionado;
				value = ((itemSelecionado != null) ? itemSelecionado.Telefone : null);
			}
			return !string.IsNullOrEmpty((string)value);
		}

		private async Task IniciarConversaWhatsApp()
		{
			WhatsAppService obj = WhatsAppService.Criar().ComProxy(DadosSistema.ObterProxy());
			Lista<AgendamentoDto> itens = Itens;
			object obj2;
			if (itens == null)
			{
				obj2 = null;
			}
			else
			{
				AgendamentoDto itemSelecionado = itens.ItemSelecionado;
				obj2 = ((itemSelecionado != null) ? itemSelecionado.Telefone : null);
			}
			WhatsAppService obj3 = obj.ComTelefone((string)obj2);
			ConfiguracaoDto configuracaoDto = DadosSistema.ConfiguracaoDto;
			object obj4;
			if (configuracaoDto == null)
			{
				obj4 = null;
			}
			else
			{
				AuxiliarDto auxiliar = configuracaoDto.Auxiliar;
				obj4 = ((auxiliar != null) ? auxiliar.MensagemWhatsApp.Valor : null);
			}
			await obj3.ComMensagemWhatsApp((string)obj4).IniciarConversa().ContinueWith(delegate(Task task)
			{
				if (task.IsFaulted)
				{
					HelperException.ShowLastException(task.Exception, "", false, false);
				}
