	public class ProximasAplicacoesFichaViewModel : FichaBase<VacinacaoDto, ProximasAplicacoesViewModel>
	{
		private Action<IEnumerable<VacinacaoDto>, bool> _retornoAction;

		public VacinacaoDto Dto { get; set; }

		public ICommand GravarCommand { get; set; }

		public ProximasAplicacoesFichaViewModel()
			: base("Próximas aplicações")
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0037: Expected O, but got Unknown
			GravarCommand = (ICommand)new DelegateCommand((Action)Gravar, (Func<bool>)PodeGravar, (bool?)null);
			base.DisableConfirmOnClose();
		}

		private bool PodeGravar()
		{
			if (HelperObject.IsNotNull((object)base.Formulario))
			{
				return base.Formulario.Valido;
			}
			return false;
		}

		private void Gravar()
		{
			try
			{
				ProximasAplicacoesViewModel proximasAplicacoesViewModel = ((Formulario)(ProximasAplicacoesFormulario)(object)base.Formulario).Abas.FirstOrDefault().ViewModel as ProximasAplicacoesViewModel;
				if (!HelperObject.IsNull((object)proximasAplicacoesViewModel))
				{
					List<VacinacaoDto> list = (from x in HelperIEnumerable.ToListEmptyWhenNull<AplicacaoGeradaViewModel>((IEnumerable<AplicacaoGeradaViewModel>)proximasAplicacoesViewModel.Aplicacoes.Itens)
						select x.VacinacaoDto).ToList();
					if (!list.Any())
					{
						DialogoFactory.MostrarDialogoConfirma("Nenhuma aplicação foi gerada.", false, System.Windows.HorizontalAlignment.Center);
						return;
					}
					_retornoAction?.Invoke(list, proximasAplicacoesViewModel.CriarAgendamentos);
					((NavigationBase)this).FecharView();
				}
			}
			catch (Exception ex)
			{
				HelperException.ShowLastException(ex, "", false, false);
			}
		}

		protected override void OnParametroInformado(object sender, NavigationParameters navigationParameters)
		{
			object obj = navigationParameters["Dto"];
			Dto = (VacinacaoDto)((obj is VacinacaoDto) ? obj : null);
			_retornoAction = navigationParameters["AplicacoesGeradas"] as Action<IEnumerable<VacinacaoDto>, bool>;
			if (HelperObject.IsNull((object)Dto))
			{
				DialogoFactory.MostrarDialogoConfirma("Selecione uma aplicação para gerar as próximas.", false, System.Windows.HorizontalAlignment.Center);
				((NavigationBase)this).FecharView();
				return;
			}
			if (navigationParameters["ProximasAplicacoesViewModel"] == null)
			{
				navigationParameters.Add("ProximasAplicacoesViewModel", (object)new ProximasAplicacoesViewModel(Dto));
			}
			base.OnParametroInformado(sender, navigationParameters);
		}
	}
