			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			//IL_0078: Expected O, but got Unknown
			Aplicacoes = new Lista<AplicacaoGeradaViewModel>();
			Unidades = new Lista<CodigoDescricaoDto>();
			Unidades.Adicionar((IEnumerable<CodigoDescricaoDto>)new List<CodigoDescricaoDto>
			{
				new CodigoDescricaoDto
				{
					Codigo = 1,
					Descricao = "dia(s)"
				},
				new CodigoDescricaoDto
				{
					Codigo = 2,
					Descricao = "mês(es)"
				},
				new CodigoDescricaoDto
				{
					Codigo = 3,
					Descricao = "ano(s)"
				}
			});
			Unidades.Posicionar((Expression<Func<CodigoDescricaoDto, bool>>)((CodigoDescricaoDto x) => x.Codigo.Equals(1)));
			DataBase = ((base.Dto.DataAplicacao == DateTime.MinValue) ? DateTime.Now : base.Dto.DataAplicacao);
			PorQuantidade = true;
			Quantidade = 3;
			Intervalo = 30;
			DataTermino = DataBase.AddYears(1);
			CriarAgendamentos = true;
		}

		private void Gerar()
		{
			try
			{
				int num = Math.Max(1, Intervalo);
				int unidade = (HelperObject.IsNull((object)Unidades.ItemSelecionado) ? 1 : Unidades.ItemSelecionado.Codigo);
				int num2 = Math.Max(1, Quantidade);
				List<VacinacaoDto> list = new List<VacinacaoDto>();
				int num3 = 1;
				while (list.Count < 120 && (!PorQuantidade || list.Count < num2))
				{
					DateTime data = AvancarData(unidade, num * num3);
					if (PorDataTermino && data.Date > DataTermino.Date)
					{
						break;
					}
					list.Add(CriarAplicacao(data));
					num3++;
				}
				SetarAplicacoes(list);
			}
			catch (Exception ex)
			{
				HelperException.ShowLastException(ex, "", false, false);
				return;
			}
			AvisarResultado();
		}

		private DateTime AvancarData(int unidade, int quantidade)
		{
			return unidade switch
			{
				2 => ComHoraDaBase(HelperDateTime.ObterDataNoDia(DataBase.AddMonths(quantidade), DataBase.Day)), 
				3 => ComHoraDaBase(HelperDateTime.ObterDataNoDia(DataBase.AddYears(quantidade), DataBase.Day)), 
				_ => DataBase.AddDays(quantidade), 
			};
		}

		private DateTime ComHoraDaBase(DateTime data)
		{
			return new DateTime(data.Year, data.Month, data.Day, DataBase.Hour, DataBase.Minute, 0);
		}

		private VacinacaoDto CriarAplicacao(DateTime data)
		{
