				Lote = base.Dto.Lote,
				LaboratorioNome = base.Dto.LaboratorioNome,
				Veterinario = base.Dto.Veterinario,
				VeterinarioReferencia = base.Dto.VeterinarioReferencia,
				NumeroDose = base.Dto.NumeroDose,
				Observacao = base.Dto.Observacao,
				DataAplicacao = data,
				Agendado = true,
				Aplicada = false,
				DavOsGerado = 0L
			};
