		private void SetarAplicacoes(IEnumerable<VacinacaoDto> geradas)
		{
			List<VacinacaoDto> list = HelperIEnumerable.ToListEmptyWhenNull<VacinacaoDto>(geradas);
			Lista<AplicacaoGeradaViewModel> val = new Lista<AplicacaoGeradaViewModel>();
			for (int i = 0; i < list.Count; i++)
			{
				AplicacaoGeradaViewModel aplicacaoGeradaViewModel = new AplicacaoGeradaViewModel(list[i], RemoverAplicacao)
				{
					Ordem = i + 1
				};
				aplicacaoGeradaViewModel.DataAplicacaoAlteradaEvent += AplicacaoOnDataAlterada;
				val.Adicionar(aplicacaoGeradaViewModel);
			}
			Aplicacoes = val;
			((BindableBase)this).RaisePropertyChanged<string>((Expression<Func<string>>)(() => QuantidadeToText));
		}

		private void RemoverAplicacao(object aplicacao)
		{
			AplicacaoGeradaViewModel aplicacaoGeradaViewModel = aplicacao as AplicacaoGeradaViewModel;
			if (!HelperObject.IsNull((object)aplicacaoGeradaViewModel))
			{
				Aplicacoes.Remover(aplicacaoGeradaViewModel);
				Renumerar();
			}
		}

		private void Renumerar()
		{
			List<AplicacaoGeradaViewModel> list = HelperIEnumerable.ToListEmptyWhenNull<AplicacaoGeradaViewModel>((IEnumerable<AplicacaoGeradaViewModel>)Aplicacoes.Itens);
			for (int i = 0; i < list.Count; i++)
			{
				list[i].Ordem = i + 1;
			}
			((BindableBase)this).RaisePropertyChanged<string>((Expression<Func<string>>)(() => QuantidadeToText));
		}

		private void AplicacaoOnDataAlterada(object sender, DataAplicacaoAlteradaEventArgs e)
		{
			if (_aplicandoCascata)
			{
				return;
			}
			AplicacaoGeradaViewModel alterada = sender as AplicacaoGeradaViewModel;
			if (HelperObject.IsNull((object)alterada))
			{
				return;
			}
			TimeSpan timeSpan = e.Nova - e.Anterior;
			if (timeSpan == TimeSpan.Zero)
			{
				return;
			}
			_aplicandoCascata = true;
			try
			{
				foreach (AplicacaoGeradaViewModel item in from x in HelperIEnumerable.ToListEmptyWhenNull<AplicacaoGeradaViewModel>((IEnumerable<AplicacaoGeradaViewModel>)Aplicacoes.Itens)
					where x.Ordem > alterada.Ordem
					select x)
				{
					item.DeslocarEm(timeSpan);
				}
			}
			finally
			{
				_aplicandoCascata = false;
			}
		}

		private void AvisarResultado()
		{
			int count = HelperIEnumerable.ToListEmptyWhenNull<AplicacaoGeradaViewModel>((IEnumerable<AplicacaoGeradaViewModel>)Aplicacoes.Itens).Count;
			if (count == 0)
			{
				DialogoFactory.MostrarDialogoConfirma("Nenhuma aplicação foi gerada. Verifique o intervalo e a data de término informados.", false, System.Windows.HorizontalAlignment.Center);
			}
			else if (count >= 120)
			{
				DialogoFactory.MostrarDialogoConfirma($"A geração parou em {120} aplicações. Reduza o período ou aumente o intervalo.", false, System.Windows.HorizontalAlignment.Center);
			}
		}

		public string ToTituloLista()
		{
			return string.Empty;
		}

		public IFormulario CriarFormulario()
		{
			return (IFormulario)(object)new ProximasAplicacoesFormulario(base.Dto);
		}

		public string ToTituloFicha()
		{
			return string.Empty;
		}
	}
}
