			ExibirLogotipo();
			PreencherProprietario();
			PreencherAnimal();
			((XRControl)razaoSocial).Text = empresaLogada.Nome;
			((XRControl)fantasia).Text = empresaLogada.Fantasia;
			((XRControl)telefone).Text = $"Telefone: {empresaLogada.Telefone}";
			((XRControl)cnpjCpfEmitente).Text = $"{arg} {empresaLogada.CpfCnpjFormatado}";
			((XRControl)cnpjCpfEmitente).Text = empresaLogada.CpfCnpjFormatado;
			((XtraReport)this).ShowPrintMarginsWarning = false;
			((XtraReport)this).CreateDocument();
			return (XtraReport)(object)this;
		}

