		private void ExibirLogotipo()
		{
			string cpfCnpj = DadosSistema.EmpresaLogada.CpfCnpj;
			if (HelperObject.IsNotNull((object)DadosSistema.EmpresaLogada.Imagem) && DadosSistema.EmpresaLogada.Imagem.Length != 0 && DadosSistema.EmpresaLogada.CpfCnpj.Equals(cpfCnpj))
			{
				logotipoEmitente.Image = HelperImage.ToImage(HelperImage.Decompress(DadosSistema.EmpresaLogada.Imagem));
			}
			((XRControl)razaoSocial).Visible = HelperObject.IsNull((object)logotipoEmitente.Image);
			((XRControl)cnpjCpfEmitente).Visible = HelperObject.IsNull((object)logotipoEmitente.Image);
			((XRControl)telefone).Visible = HelperObject.IsNull((object)logotipoEmitente.Image);
			((XRControl)logotipoEmitente).Visible = !HelperObject.IsNull((object)logotipoEmitente.Image);
			((XRControl)fantasia).Visible = HelperObject.IsNull((object)logotipoEmitente.Image);
		}

