			((XRControl)telefone).Text = $"Telefone: {empresaLogada.Telefone}";
			((XRControl)cnpjCpfEmitente).Text = $"{arg} {empresaLogada.CpfCnpjFormatado}";
			((XRControl)municipioDataHora).Text = $"{empresaLogada.Municipio.Nome}-{empresaLogada.Municipio.Uf.Sigla}, {HelperDate.FormatarData(DateTime.Now.Date, (FormatoData)6)}";
