				obj2 = ((personalizado != null) ? new bool?(personalizado.Campos.Any((CampoPersonalizadoDto x) => x.ExibirImpressao)) : null);
			}
			((XRControl)obj).Visible = obj2 ?? false;
			XRRichText obj3 = xrRichText24;
			AnimalDto animal2 = _animal;
			object obj4;
